import{createClient}from"https://esm.sh/@supabase/supabase-js@2";import{SUPABASE_URL,SUPABASE_ANON_KEY}from"./supabase-config.js";const supabase=createClient(SUPABASE_URL,SUPABASE_ANON_KEY),$=s=>document.querySelector(s);let rows=[];const labels={new:"جديد",reviewing:"تحت المراجعة",inspection_scheduled:"تم تحديد المعاينة",quoted:"صدر عرض السعر",approved:"معتمد",scheduled:"مجدول",in_progress:"قيد التنفيذ",completed:"مكتمل",cancelled:"ملغي"};
$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.currentTarget),{error}=await supabase.auth.signInWithPassword({email:f.get("email"),password:f.get("password")});$("#message").textContent=error?error.message:""});$("#logoutBtn").onclick=()=>supabase.auth.signOut();$("#refreshBtn").onclick=load;$("#search").oninput=render;$("#statusFilter").onchange=render;
async function sessionView(session){if(!session){$("#adminLogin").classList.remove("hidden");$("#adminView").classList.add("hidden");$("#logoutBtn").classList.add("hidden");return}const{data}=await supabase.from("pr_profiles").select("role").eq("id",session.user.id).single();if(!['admin','sales','operations'].includes(data?.role)){await supabase.auth.signOut();$("#message").textContent="هذا الحساب لا يملك صلاحية الإدارة";return}$("#adminLogin").classList.add("hidden");$("#adminView").classList.remove("hidden");$("#logoutBtn").classList.remove("hidden");load()}
async function load(){const{data,error}=await supabase.from("pr_service_requests").select("*,pr_profiles(full_name,phone)").order("created_at",{ascending:false});if(error){$("#adminRequests").innerHTML=`<p class="empty">${error.message}</p>`;return}rows=data||[];$("#newCount").textContent=rows.filter(x=>x.status==='new').length;$("#doneCount").textContent=rows.filter(x=>x.status==='completed').length;$("#activeCount").textContent=rows.filter(x=>!['new','completed','cancelled'].includes(x.status)).length;render()}
function render(){const q=$("#search").value.trim().toLowerCase(),status=$("#statusFilter").value;const data=rows.filter(x=>(!status||x.status===status)&&(!q||`${x.request_no} ${x.pr_profiles?.full_name||''}`.toLowerCase().includes(q)));$("#adminRequests").innerHTML=data.length?data.map(x=>`<article class="admin-request"><div><b>${x.request_no}</b><h3>${x.service_type}</h3><small>${x.pr_profiles?.full_name||'—'} · ${x.pr_profiles?.phone||'—'}</small></div><div><span>${x.property_type} · ${x.city} · ${x.district}</span><small>${new Date(x.created_at).toLocaleString('ar-SA')}</small></div><select class="status-select" data-id="${x.id}">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===x.status?'selected':''}>${v}</option>`).join('')}</select></article>`).join(''):'<p class="empty">لا توجد نتائج.</p>';document.querySelectorAll('.status-select').forEach(el=>el.onchange=async()=>{el.disabled=true;const{error}=await supabase.from('pr_service_requests').update({status:el.value}).eq('id',el.dataset.id);el.disabled=false;if(error)alert(error.message)})}
const{data:{session}}=await supabase.auth.getSession();sessionView(session);supabase.auth.onAuthStateChange((_e,s)=>setTimeout(()=>sessionView(s),0));
